package blockbranch.realistic;
import java.util.*;
public final class SnowyPlainsCheck {
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);var e=new GroundEcology.Field(d::sample,c);int count=0,tundra=0,retained=0,gainedBare=0;for(int z=-1900000;z<=1900000;z+=16000)for(int x=-1900000;x<=1900000;x+=16000){boolean old=ColdTundra.contains(x,z,d,c),selected=SnowyPlains.contains(x,z,d,c);if(old){tundra++;if(!selected)retained++;}if(!selected)continue;count++;if(!old)gainedBare++;require(!LandVegetation.reserved(d,x,z)&&!BorealWoodland.contains(seed,x,z,d,c)&&!ColdSteppe.contains(x,z,d,c),"Preserve scree,wet domains,boreal and cold steppe");require(SlopeCorrection.slope(d,x,z)<=.2&&SnowyPlains.climateSuitable(c.sample(x,z,d::sample)),"Actual cold gentle open land");}
 require(count>=5&&retained>=tundra*.7,"Meaningful plains and substantial retained tundra");var p=blockbranch.realistic.SnowyPlainsFixtures.fixture(d,seed);var arrays=new LinkedHashMap<String,int[]>();int snow=0,gaps=0;var layerCounts=new HashSet<Integer>();for(int cz=(p.z()>>4)-2;cz<=(p.z()>>4)+2;cz++)for(int cx=(p.x()>>4)-2;cx<=(p.x()>>4)+2;cx++){var a=OpenSnowCover.plainsColumn(seed,cx,cz,new int[0],d,c,e);require(a.length<=256,"Bounded one-layer terrain snow");arrays.put(cx+","+cz,a);snow+=a.length;gaps+=256-a.length;for(int v:a){int k=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,code=v&blockbranch.cubic.CanopyLayer.STATE_MASK,wx=cx*16+(k&15),wz=cz*16+((k>>>4)&15),y=(k>>>8)+TerrainShape.FLOOR;require(SnowyTaiga.snow(code)&&y==d.sample(wx,wz).height()+1&&d.sample(wx,wz).waterLevel()==DrainageNetwork.DRY,"Supported dry native snow only");layerCounts.add(code);}}require(snow>1000&&layerCounts.size()>=2,"Coherent varied-depth snow cover");var keys=new ArrayList<>(arrays.keySet());Collections.reverse(keys);for(var key:keys){var q=key.split(",");require(Arrays.equals(arrays.get(key),OpenSnowCover.plainsColumn(seed,Integer.parseInt(q[0]),Integer.parseInt(q[1]),new int[0],d,c,e)),"Global negative-coordinate/chunk-order stability");}
 System.out.println("SNOWY_PLAINS seed="+seed+" selected="+count+" retainedTundra="+retained+" priorTundra="+tundra+" gainedBare="+gainedBare+" point="+p+" snow="+snow+" gaps="+gaps+" layers="+layerCounts);}
 System.out.println("SNOWY_PLAINS_CLIMATE_RELIEF_RETAINED_DOMAINS_SUPPORT_SEAMS_PASS");}
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
